######## Comando para reorg via brtools (faz move das tabelas do owner SAPSR3 para a nova tablespace)
- TODAS AS TABELAS DO SCHEMA SAPSR3, MOVE PARA A TABLESPACE PSAPSR3NEW
no AIX, setar as variáveis de ambiente executar o comando:

setenv BR_MSL 10485760
setenv BR_DBL 41943040
brspace -u / -c force -f tbreorg -o SAPSR3 -t "*" -n PSAPSR3NEW -p 6 -m online -e 6 | tee reorg_tudo.log

######## CASO NÃO MOVA TODAS AS TABELAS, EXECUTAR ABAIXO PARA AS TABELAS COM CAMPOS "LONG" SCHEMA SAPSR3:
setenv BR_MSL 10485760
setenv BR_DBL 41943040
brspace -u / -c force -f tbreorg -a long2lob -o SAPSR3 -t "*" -n PSAPSR3NEW -p 6 -m online | tee reorg_long.log

########  SE OCORRER ERRO PARA ALGUMA TABELA, EXECUTAR O MOVE POR TABELA:
setenv BR_MSL 10485760
setenv BR_DBL 41943040
brspace -u / -c force -f tbreorg -o SAPSR3 -t "nome_tabela1" -n PSAPSR3NEW -p 3 -m online -e 3 | tee reorg_tabel1.log
brspace -u / -c force -f tbreorg -o SAPSR3 -t "nome_tabela2" -n PSAPSR3NEW -p 3 -m online -e 3 | tee reorg_tabel2.log
brspace -u / -c force -f tbreorg -o SAPSR3 -t "nome_tabela3" -n PSAPSR3NEW -p 3 -m online -e 3 | tee reorg_tabel3.log
brspace -u / -c force -f tbreorg -o SAPSR3 -t "nome_tabelaN" -n PSAPSR3NEW -p 3 -m online -e 3 | tee reorg_tabelN.log

######## SE RESTAREM TABELAS PARTICIONADAS QUE NÃO FORAM MIGRADAS, MIGRAR DIRETO NO BANCO DE DADOS:
select 'alter table SAPSR3."' ||TABLE_NAME|| '" move partition "' || partition_name|| '" tablespace PSAPSR3NEW parallel 6;' "PARTITION_MOVE_SCRIPT" 
from DBA_TAB_PARTITIONS WHERE table_name='tabela_n'; 

########  SE RESTAREM INDICES PARTICIONADOSM, REALIZAR REBUILD DIRETO NO BANCO:
select 'alter index SAPSR3."' || a.index_name ||  '" rebuild partition "' || a.PARTITION_NAME || '" tablespace PSAPSR3NEW parallel 6;' 
from DBA_IND_PARTITIONS  a, DBA_TAB_PARTITIONS  b where a.partition_name=b.partition_name and b.table_name='table_n';
